  async function protectedFile(path,{preview=false,filename=''}={}){const u=new URL(path,location.origin);if(!protectedPath(u.href))throw new Error('앱에 저장한 파일 주소를 확인해 주세요.');if(!await ensureWorkAdmin())return false;const htmlPreview=preview&&/\.html$/.test(u.pathname);let opened=htmlPreview?window.open('about:blank','_blank'):null;if(opened)opened.opener=null;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),120000);try{const res=await fetch(u.pathname+u.search,{headers:{'X-Admin-Token':state.adminToken},credentials:'same-origin',redirect:'error',signal:controller.signal});if(!res.ok){if(res.status===401||res.status===403){clearPrivateWork();render();}throw new Error('파일을 받지 못했어요. 관리자 확인 후 다시 눌러 주세요.');}let blob=await res.blob();const type=res.headers.get('Content-Type')||'';if(preview&&type.startsWith('text/html')){const text=await blob.text();const base=`<base href="${esc(location.origin)}/"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; script-src ${esc(location.origin)}/print.js; base-uri ${esc(location.origin)}; form-action 'none'">`;blob=new Blob([text.replace(/<head>/i,`<head>${base}`)],{type:'text/html;charset=utf-8'});}const objectUrl=URL.createObjectURL(blob);protectedObjectUrls.add(objectUrl);if(opened){opened.location.replace(objectUrl);return true;}let name=filename;const disposition=res.headers.get('Content-Disposition')||'';if(!name){const encoded=/filename\*=UTF-8''([^;]+)/i.exec(disposition);try{name=encoded?decodeURIComponent(encoded[1]):'';}catch(e){name='';}}name=(name||u.pathname.split('/').at(-1)||'aroma-file').replace(/[\\/\x00-\x1f]/g,'_');const link=document.createElement('a');link.href=objectUrl;link.download=name;document.body.append(link);link.click();link.remove();if(preview)toast('미리보기 창이 차단되어 파일 사본을 내려받았어요.');return true;}catch(e){if(opened&&!opened.closed)opened.close();throw e;}finally{clearTimeout(timer);}}
