  async function resetAfterFullBackup(){clearTimeout(state.active?.saveTimer);clearTimeout(state.aiTimer);try{const keys=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(/^aroma\.(pending\.|ai(?:\.|-)|native-review\.|png-export\.)/.test(key))keys.push(key);}keys.forEach(key=>localStorage.removeItem(key));}catch(e){}state.active=null;state.ai=null;state.aiTimer=null;state.nativeEditor=null;state.studio=null;state.pngPending=undefined;state.pngBusy=false;state.pngEpoch=(state.pngEpoch||0)+1;state.adminToken='';state.importer=null;const fresh=await api('/api/bootstrap');state.boot={...fresh,programs:fresh.programs?.programs||fresh.programs||[],files:fresh.files?.files||fresh.files||[],quotes:fresh.quotes?.quotes||fresh.quotes||[],plans:fresh.plans?.plans||fresh.plans||[]};state.token=fresh.csrf_token||fresh.token||'';state.fullBackupUncertain=false;fullBackupControls();}
