  function updateControls(){const held=!!state.updateBusy;$$('[data-nav="quote"],[data-nav="plan"],[data-action],[data-field],[data-native-field],[data-ai-field],input[type="file"]').forEach(b=>{if(b.matches('[data-action]')&&!FULL_WORK_ACTIONS.includes(b.dataset.action)&&!['full-backup','shutdown'].includes(b.dataset.action))return;if(held){if(!b.hasAttribute('data-update-blocked'))b.dataset.updatePreviouslyDisabled=String(b.disabled);b.dataset.updateBlocked='true';b.disabled=true;}else if(b.hasAttribute('data-update-blocked')){b.disabled=b.dataset.updatePreviouslyDisabled==='true';delete b.dataset.updateBlocked;delete b.dataset.updatePreviouslyDisabled;}});if(held&&state.page!=='updates'&&!$('#update-hold')){const el=document.createElement('div');el.id='update-hold';el.className='notice warn';el.innerHTML='<div><strong>업데이트 상태를 확인 중이에요</strong><p>입력을 보관하며 다시 연결되는 상태를 확인합니다. 적용을 반복하지 않습니다.</p><button class="btn secondary" data-action="open-updates">업데이트 상태 확인</button></div>';$('#main')?.prepend(el);}else if(!held||state.page==='updates')$('#update-hold')?.remove();}
