  async function updateAdmin(){if(state.adminToken)return state.adminToken;const answer=await dialog('업데이트 관리자 확인','<p>새 버전 확인과 적용을 위한 관리자 PIN을 확인합니다.</p><div class="field"><label for="update-admin-pin">관리자 PIN</label><input id="update-admin-pin" type="password" inputmode="numeric" autocomplete="off" minlength="6" maxlength="12"><p class="field-hint">PIN이 없다면 6~12자리 숫자로 처음 설정하세요. PIN은 이 창의 메모리에서만 사용합니다.</p></div>',[{label:'기존 PIN으로 확인',value:'login'},{label:'처음 PIN 설정',value:'setup',secondary:true},{label:'취소',value:'cancel',secondary:true}]);if(!['login','setup'].includes(answer))return '';const pin=$('#update-admin-pin')?.value||'';if(!/^\d{6,12}$/.test(pin)){toast('PIN은 6~12자리 숫자로 입력해 주세요.',true);return '';}try{let r=await api(`/api/admin/${answer}`,{method:'POST',body:{pin,request_id:uid()}});if(answer==='setup'&&!r.admin_token&&!r.token&&!r.session_token)r=await api('/api/admin/login',{method:'POST',body:{pin,request_id:uid()}});state.adminToken=r.admin_token||r.token||r.session_token||'';if(!state.adminToken)throw Error('admin_response_invalid');await refreshProtectedWork();return state.adminToken;}catch(e){state.adminToken='';toast(e.status===401?'PIN을 다시 확인해 주세요.':e.status===409?'이미 PIN이 있어요. 기존 PIN으로 확인해 주세요.':'관리자 확인을 마치지 못했어요. 앱 실행 상태를 확인해 주세요.',true);return '';}}
