  async function showUpdateNoticeInfo(status){if(state.updateNoticeDialog)return;state.updateNoticeDialog=true;let answer;try{const s=status||state.updateNotice?.getStatus?.()||{};const explanations={idle:'새 버전을 확인할 준비가 되었어요.',checking:'새 버전을 확인 중이에요. 다른 작업을 계속해도 됩니다.',up_to_date:'현재 확인한 새 버전이 없습니다.',available:'새 버전 안내가 있어요. 설치는 사용자가 승인한 뒤에만 진행합니다.',incompatible:'현재 업무 자료의 형식과 공개 버전이 달라 바로 적용할 수 없어요. 새 설치와 자료 이관 방법을 아들과 확인해 주세요.',offline:'지금 버전 정보를 확인하지 못했어요. 기존 업무는 계속할 수 있습니다.',timeout:'확인이 오래 걸려 멈췄어요. 기존 업무는 계속할 수 있습니다.',invalid:'새 버전 정보를 안전하게 확인하지 못했어요. 기존 앱을 계속 사용하세요.',recovery_required:'이전 업데이트의 자료 상태를 먼저 확인해야 해요.'};const reason=s.apply_disabled_reason==='schema_incompatible'?explanations.incompatible:'새 버전 적용은 앱 업데이트 화면에서 관리자 PIN과 마지막 확인을 거칩니다. 자동으로 설치하지 않습니다.';answer=await dialog('앱 업데이트 안내',`<p>${esc(explanations[s.state]||'버전 정보를 확인할 수 있어요.')}</p><p>현재 버전: ${esc(String(s.current_version||state.boot?.version||'확인 전').slice(0,100))}</p>${s.candidate?.version?`<p>확인한 버전: ${esc(String(s.candidate.version).slice(0,100))}</p>`:''}<p class="field-hint">${esc(reason)}</p>`,[{label:'앱 업데이트 화면',value:'updates'},{label:'다시 확인',value:'check',secondary:true},{label:'나중에',value:'later',secondary:true}]);}finally{state.updateNoticeDialog=false;}if(answer==='updates'){openUpdates();return;}if(answer==='check'){await state.updateNotice?.manualCheck();toast('버전 확인을 요청했어요. 다른 작업을 계속해도 됩니다.');}}
