  function select(label,key,value,options,hint='') { const id=`f-${key}`; return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}" data-field="${esc(key)}">${options.map(o=>`<option value="${esc(o[0])}" ${String(value)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select><p class="field-hint">${esc(hint)}</p><p class="field-error" data-error="${esc(key)}" hidden></p></div>`; }
