    if(a==='adopt-sessions'){const p=currentProgram(d.form);if(d.form.sessions.length){const ans=await dialog('입력한 회차를 후보로 바꿀까요?','<p>지금 입력한 회차를 프로그램의 확인 필요 후보로 바꿉니다. ‘입력 되돌리기’로 돌아갈 수 있습니다.</p>',[{label:'후보 회차 가져오기',value:'yes'},{label:'취소',value:'cancel',secondary:true}]);if(ans!=='yes')return;}track(d);d.form.sessions=(p.sessions||[]).map((s,i)=>({...clone(s),week:i+1,description:s.description||s.goal||'',activity_confirmed:false}));d.form.session_count=p.session_count||d.form.sessions.length;if(!d.form.goals)d.form.goals=p.goal||'';changed(d);render();return;}
    if(a==='undo-local'){if(!d.history.length)return;d.form=d.history.pop();editBefore=null;changed(d);render();toast('직전 입력으로 되돌렸어요.');return;}
    if(a==='save-draft'){b.disabled=true;await saveDocument(d,false,false);if(b.isConnected)b.disabled=false;return;}
