    if(a==='ai-image-prepare'){await prepareAiImage();return;}if(a==='image-setup'){openImageSetup();return;}if(a==='ai-history'){await showAiHistory();return;}if(a==='ai-open-history'){await openAiHistory(b.dataset.id);return;}if(a==='ai-prepare'){await prepareAi();return;}if(a==='ai-preview'){await previewAi();return;}if(a==='ai-start'){await startAi();return;}if(a==='ai-retry-start'){await startAi(true);return;}if(a==='ai-check-status'){b.disabled=true;await refreshAiStatus();if(b.isConnected)b.disabled=false;return;}if(a==='ai-setup-help'){await aiSetupHelp();return;}if(a==='ai-edit'){state.ai.phase='choose';state.ai.preview=null;state.ai.sendConsent=false;saveAiLocal();render();return;}if(a==='ai-back-studio'){setPage('studio');return;}if(a==='ai-refresh-job'){await refreshAiJob();return;}if(a==='ai-cancel'){await cancelAi();return;}if(a==='ai-reset'){clearTimeout(state.aiTimer);state.ai.job=null;state.ai.pendingStart=null;state.ai.preview=null;state.ai.phase='choose';state.ai.sendConsent=false;state.ai.includeContacts=false;state.ai.includeFields=state.ai.includeFields.filter(k=>!['phone','email'].includes(k));state.ai.error='';saveAiLocal();render();return;}if(a==='ai-resume'){await resumeAi();return;}if(a==='ai-native-review'){openNativeReview(b.dataset.kind);return;}if(a==='ai-use-for-ppt'){useAiForPpt();return;}if(a==='studio-draft'){b.disabled=true;await studioDraft();if(b.isConnected)b.disabled=false;return;}
